UPDATE PRJ_TASK
SET 
	USER_ID = #{userId}
	, SECT_NO = #{sectNo}
	, TASK_NAME = #{taskName}
	, TASK_STATUS = #{taskStatus}
	, DETAIL_CONTENT = #{detailContent}
	, START_DATE = #{startDate}
	, DUE_DATE = #{dueDate}
	, PRIORITY_CODE = #{priorityCode}
	, UPPER_TASK_NO = #{upperTaskNo}
	, PROGRESS_RATE = #{progressRate}
	, DELETE_DATE = #{deleteDate}
	, DELETE_USER_ID = #{deleteUserId}
WHERE TASK_NO = #{taskNo}

mapper.select:
SELECT t.task_no, t.prj_no, t.user_id, t.sect_no, t.creator_id, t.task_name, t.task_status, t.detail_content, t.start_date, t.due_date, t.priority_code, t.upper_task_no, t.progress_rate, t.delete_date, t.delete_user_id, m.user_name, m.user_position FROM prj_task t LEFT JOIN prj_section s ON t.sect_no = s.sect_no LEFT JOIN prj_mem m ON t.prj_no = m.prj_no AND t.user_id = m.user_id WHERE t.prj_no = #{prjNo}
AND T.TASK_STATUS = #{status}
AND T.USER_ID = #{userId}
AND t.delete_date is NULL order by t.start_date asc

